string datetime = DateTime.Now.ToUniversalTime().ToString("yyMMddTHHmmssZ");
string message = $"{datetime}{method}{path}{query}";
var hmac = new HMACSHA256(Encoding.ASCII.GetBytes(secretKey));
byte[] hash = hmac.ComputeHash(Encoding.ASCII.GetBytes(message));
string signature = string.Concat(hash.Select(b => b.ToString("x2")));
string authorization = $"CEA algorithm=HmacSHA256, access-key={accessKey}, signed-date={datetime}, signature={signature}";
